/*
 * csi_presence.h - on-device presence classifier fed by raw CSI records.
 *
 * Requires (generated by model-training-scripts/csi_train_export.py, copy into source/):
 *     csi_model.h, csi_model_config.h   (and csi_selftest.h if SELFTEST is 1)
 * UART/control settings live in csi_uart_out.h.
 */
#ifndef CSI_PRESENCE_H_
#define CSI_PRESENCE_H_

#include <stddef.h>
#include <stdint.h>

/* Majority vote over the last N classifications. 1 = no smoothing (default):
 * every prediction is acted on and "confidence" is the model's tree-vote share.
 * With N > 1, "confidence" becomes the share of the last N results that agree. */
#ifndef CSI_VOTE_N
#define CSI_VOTE_N 1U
#endif

/* 1 = at boot, run the embedded test windows through featurize + model.
 * A failure latches the control output OFF ("fault") until reboot. */
#ifndef CSI_PRESENCE_SELFTEST
#define CSI_PRESENCE_SELFTEST 1
#endif

/* Optional: define CSI_PRES_OUT_HOOK(cls) to drive a GPIO/LED from the class.
 * Optional (host tests): define CSI_PRES_FEATURE_HOOK(feat, n) to see every
 * feature vector before it goes into the model. */

/* Starts the output task (csi_uart_out.c) and runs the self-test if enabled.
 * Returns 0 on success. On failure the classifier stays disabled and, if the
 * output task is running, control is latched OFF. */
int csi_presence_init(void);

/* Milliseconds since the last valid record from the AP was accepted. */
uint32_t csi_presence_ms_since_feed(void);

/* Records rejected by validation (bad header, or a different data size than trained). */
uint32_t csi_presence_rejected(void);

/* Feed ONE complete raw CSI record (48-byte header | CSI data | 4-byte tail).
 * Call from a task, never from the Wi-Fi driver callback. Ignored while disabled. */
void csi_presence_feed(const uint8_t *rec, size_t len);

#endif /* CSI_PRESENCE_H_ */
